def data_de(epoch):
    return datetime.fromtimestamp(int(epoch), tz=timezone.utc).strftime("%Y-%m-%d")

CAB_T = ["data", "lote", "termo", "indice", "geo", "janela", "fonte", "url_fonte", "observacao"]
linhas = []
for lote, kws, csvs in (("candidatos_a", LOTE_A, CSV_A), ("candidatos_b", LOTE_B, CSV_B), ("termos", TERMOS, CSV_T)):
    obs = ""
    if lote == "candidatos_b":
        obs = "lote separado (máx. 5 termos por consulta); Lula repetido como âncora para comparação com o lote A"
    for pt in csvs.split("|"):
        t, vals = pt.split(";")
        d = data_de(t)
        for kw, v in zip(kws, vals.split(",")):
            linhas.append([d, lote, kw, int(v), "BR", "2026-01-01 a 2026-09-01, diário", FONTE_T, URL_T,
                           (obs + ("; " if obs and d == "2026-08-16" else "") + ("dia zerado na resposta do Google, tratar como lacuna" if v == "0" and d == "2026-08-16" and kw == kws[0] else "")) if (obs or d == "2026-08-16") else ""])
print("trends: dia zerado detectado em", data_de(1786838400))
gravar("trends-2026.csv", CAB_T, linhas)

PV = __import__("json").load(io.open(os.path.join(BASE, "_pv_bruto.json"), encoding="utf-8"))
TITULOS = {"Lula": "Luiz Inácio Lula da Silva", "Flávio Bolsonaro": "Flávio Bolsonaro", "Augusto Cury": "Augusto Cury",
           "Ronaldo Caiado": "Ronaldo Caiado", "Romeu Zema": "Romeu Zema", "Renan Santos": "Renan Santos",
           "Pablo Marçal": "Pablo Marçal", "Samara Martins": "Samara Martins"}
CAB_W = ["data", "candidato", "artigo", "pageviews", "fonte", "url_fonte", "observacao"]
lw = []
for cand, s in PV.items():
    for par in s.split(","):
        mmdd, v = par.split(":")
        obs = ""
        if cand == "Samara Martins" and mmdd == "0409": obs = "verbete criado em abril de 2026; série começa aqui"
        if cand == "Renan Santos" and mmdd == "0101": obs = "verbete 'Renan Santos' (fundador do MBL); série corrigida em 1/9 à noite: a coleta anterior usara por engano o verbete do futebolista Renan dos Santos"
        lw.append([f"2026-{mmdd[:2]}-{mmdd[2:]}", cand, TITULOS[cand], int(v), FONTE_W,
                   f"https://pt.wikipedia.org/wiki/{TITULOS[cand].replace(' ', '_')}", obs])
lw.sort(key=lambda r: (r[0], r[1]))
gravar("wikipedia-pageviews.csv", CAB_W, lw)

